@layer nz.tokens, nz.themes, nz.reset, nz.base, nz.components, nz.patterns, nz.utilities;


@layer nz.components {
  .nz-bulk-action-bar {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--nz-space-2) var(--nz-space-4);
    box-sizing: border-box;
    min-block-size: var(--nz-space-12);
    padding-block: var(--nz-space-2);
    padding-inline: var(--nz-space-3);
    border: var(--nz-border-width-default) solid var(--nz-border-subtle);
    border-radius: var(--nz-radius-md);
    background: var(--nz-bulk-action-bar-bg, var(--nz-bg-subtle));
  }

  .nz-bulk-action-bar-count {
    color: var(--nz-text-primary);
    font: var(--nz-font-label-m-strong);
    letter-spacing: var(--nz-tracking-label-m);
    font-variant-numeric: tabular-nums;
  }

  .nz-bulk-action-bar-actions {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--nz-space-2);
    margin-inline-start: auto;
  }

  @media (forced-colors: active) {
    .nz-bulk-action-bar {
      border-color: CanvasText;
    }
  }

  /* Optical centring (M85, as Button's label): trimmed to cap height and baseline, padded back to
     one line, so the box keeps its height and the letters sit in its middle. */
  @supports (text-box: trim-both cap alphabetic) {
    .nz-bulk-action-bar-count {
      padding-block: calc((1lh - 1cap) / 2);
      text-box: trim-both cap alphabetic;
    }
  }
}
